]

LUA_PATTERNS = [
    (b"hello world", b"o", b"OO"),
    (b"aaaa", b"aa", b"b"),
    (b"a_b_c", b"_", b"-"),
]

FILENAMES = [
    b"/dev/null", b"/etc/hosts", b"./script.lua", b"/tmp/chunk.lua",
    b"@stdin", b"chunkname", b"NUL", b"CON",
]


def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


def _with_nuls(r: random.Random, base: bytes) -> bytes:
    if not base:
        base = b"x"
    data = bytearray(base)
    for _ in range(r.randint(0, 3)):
        pos = r.randrange(0, len(data) + 1)
        data[pos:pos] = b"\x00"
    return bytes(data)


def _emit_record(buf: bytearray, tag: int, payload: bytes) -> bool:
    # Truncate payload to fit remaining capacity and 16-bit length
    remaining_header = MAX_TOTAL - len(buf)
    if remaining_header < 3:
        return False
    max_len = min(65535, MAX_TOTAL - len(buf) - 3)
    if max_len <= 0:
        return False
    payload = payload[:max_len]
    buf.append(tag & 0xFF)
    buf.extend(struct.pack('>H', len(payload)))
    buf.extend(payload)
    return True


def _emit_str(buf: bytearray, s: bytes) -> bool:
    return _emit_record(buf, 0x01, s)


def _emit_filename(buf: bytearray, s: bytes) -> bool:
    return _emit_record(buf, 0x02, s)


def _emit_uint(buf: bytearray, v: int) -> bool:
    return _emit_record(buf, 0x03, struct.pack('>I', v & 0xFFFFFFFF))


def _gen_interesting_strings(r: random.Random) -> List[bytes]:
    base: List[bytes] = []
    base.extend(ASCII_WORDS)
    base.extend(NUMERIC_STRINGS)
    base.extend(LUA_SNIPPETS)
    base.extend([s.encode('utf-8') for s in UTF8_SNIPPETS])
    for s, p, rr in LUA_PATTERNS:
        base.append(s + b"\x1f" + p + b"\x1f" + rr)
    # Random binary/text
    for _ in range(10):
        n = r.randint(0, 64)
        base.append(_rand_bytes(r, n))
    for _ in range(6):
        base.append(_with_nuls(r, _rand_bytes(r, r.randint(1, 48))))
    for _ in range(4):
        base.append(_rand_bytes(r, r.randint(128, 512)))
    # Shuffle deterministically by seed
    r.shuffle(base)
    # Select a variable subset length depending on seed
    take = 20 + r.randrange(0, min(40, len(base)))
    return base[:take]


def _gen_uints(r: random.Random) -> List[int]:
    vals = [0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1023, 1024]
    vals += [0xFFFFFFFF, 0x80000000, 0x7FFFFFFF]
    for _ in range(12):
        vals.append(r.getrandbits(32))
    r.shuffle(vals)
    return vals[: 10 + r.randrange(0, len(vals) - 10)]


def _gen_filenames(r: random.Random) -> List[bytes]:
    outs = list(FILENAMES)
    for i in range(6):
        stem = f"file_{i}_{r.randrange(1000)}.lua".encode()
        outs.append(stem)
        outs.append(b"./" + stem)
    outs.append("my chunk.lua".encode())
    outs.append("脚本.lua".encode('utf-8'))
    r.shuffle(outs)
    return outs[: 6 + r.randrange(0, len(outs) - 6)]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    buf = bytearray()

    # Seed-specific header containing the seed value (helps uniqueness)
    _emit_record(buf, 0x7F, struct.pack('>I', seed & 0xFFFFFFFF))

    # Emit a seed-varied number of unsigned ints
    for v in _gen_uints(r):
        if not _emit_uint(buf, v):
            break

    # Emit a shuffled, seed-sized selection of strings
    for s in _gen_interesting_strings(r):
        if not _emit_str(buf, s):
            break

    # Emit filenames (some loaders use these)
    for f in _gen_filenames(r):
        if not _emit_filename(buf, f):
            break

    # Always end with a couple of canonical values
    _emit_str(buf, b"")
    _emit_str(buf, b"12345")

    return bytes(buf[:MAX_TOTAL])

import random
import string
from typing import List, Tuple

# Target: Generate buffers for Lua chunk loading APIs (luaL_loadbuffer / luaL_loadbufferx).
# FUZZ_PARAM_STR will consume our bytes as seedable input; typical harnesses split the input
# stream into sequential parameters. We therefore pack multiple logical strings (buffer + name + extras)
# into a single bytes blob separated by NULs. The stubs need:
#  - buf: arbitrary Lua chunk bytes (source or bytecode). We will generate valid Lua source text.
#  - name: chunk name (C string). Provide interesting names ("=..." or "@...").
#  - mode for luaL_loadbufferx is chosen independently by the fuzzer; we still keep source valid.
# Keep total size <= 4096 bytes.

LUA_KEYWORDS = [
    "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
    "goto", "if", "in", "local", "nil", "not", "or", "repeat", "return",
    "then", "true", "until", "while"
]

BUILTINS = [
    "print", "pairs", "ipairs", "next", "type", "tostring", "tonumber",
    "assert", "error", "pcall", "xpcall", "select", "rawget", "rawset",
    "rawequal", "setmetatable", "getmetatable", "table.concat", "table.insert",
    "table.sort", "math.sin", "math.cos", "math.sqrt", "math.random",
]

STRING_SAMPLES = [
    "hello", "", "a\\0b", "ümlaut", "newline\n", "tab\t", "quotes ' \"",
]

def _rand_ident(r: random.Random, minlen=1, maxlen=12) -> str:
    first = r.choice(string.ascii_letters + "_")
    rest = ''.join(r.choice(string.ascii_letters + string.digits + "_") for _ in range(r.randint(minlen-1, maxlen-1)))
    return first + rest

def _rand_number(r: random.Random) -> str:
    choice = r.randrange(6)
    if choice == 0:
        return str(r.randint(-2**31, 2**31-1))
    if choice == 1:
        return f"{r.uniform(-1e6, 1e6):.6f}"
    if choice == 2:
        # hex integer
        return hex(r.randint(0, 2**32-1))
    if choice == 3:
        # scientific
        return f"{r.uniform(1e-9, 1e9):.6e}"
    if choice == 4:
        # edge-like
        return r.choice(["0", "1", "-1", "1/0", "-1/0", "0/0"])  # Lua will parse as arithmetic
    return str(r.randrange(0, 1000))

def _rand_string_literal(r: random.Random) -> str:
    s = r.choice(STRING_SAMPLES)
    # Occasionally generate long-bracket literal to test parser
    if r.random() < 0.2:
        eqs = "=" * r.randrange(0, 3)
        return f"[{eqs}[{s}]{eqs}]"
    # Regular quoted with escapes
    s2 = s.replace("\\", "\\\\").replace("\"", "\\\"")
    return f'"{s2}"'

def _gen_local_defs(r: random.Random, n: int) -> List[str]:
    lines = []
    for _ in range(n):
        name = _rand_ident(r)
        kind = r.randrange(5)
        if kind == 0:
            lines.append(f"local {name} = {_rand_number(r)}")
        elif kind == 1:
            lines.append(f"local {name} = {_rand_string_literal(r)}")
        elif kind == 2:
            lines.append(f"local {name} = {{ a = 1, b = 2, [3] = 4 }}")
        elif kind == 3:
            fn = _rand_ident(r)
            lines.append(f"local function {name}(x) return x, {fn} end")
        else:
            lines.append(f"local {name} = {r.choice(['true','false','nil'])}")
    return lines

def _gen_function(r: random.Random) -> str:
    fname = _rand_ident(r)
    args = ", ".join(_rand_ident(r) for _ in range(r.randint(0, 3)))
    body = []
    # Some operations
    for _ in range(r.randint(1, 4)):
        op = r.randrange(6)
        if op == 0:
            body.append(f"local x = {_rand_number(r)} + {_rand_number(r)}")
        elif op == 1:
            body.append(f"local s = {_rand_string_literal(r)} .. {_rand_string_literal(r)}")
        elif op == 2:
            body.append("local t = {1,2,3}; t[#t+1] = 4")
        elif op == 3:
            body.append(f"if {r.choice(['true','false','nil'])} then return end")
        elif op == 4:
            body.append(r.choice(["for i=1,3 do end", "while false do break end"]))
        else:
            body.append(r.choice(["local f = function(y) return y end", "local mt = {}; setmetatable({}, mt)"]))
    if r.random() < 0.5:
        body.append(r.choice(["return 1", "return 'ok'", "return true, false"]))
    inner = "\n  ".join(body)
    return f"function {fname}({args})\n  {inner}\nend"\
           + ("\n" + fname + "()" if r.random() < 0.5 else "")

def _gen_chunk(r: random.Random, target_bytes: int) -> str:
    parts: List[str] = []
    # Shebang sometimes (Lua ignores if at start of file as a comment when using interpreter, still valid text)
    if r.random() < 0.3:
        parts.append("-- fuzz chunk\n")
    # Generate locals
    parts.extend(_gen_local_defs(r, r.randint(1, 6)))
    # Optionally require standard libs via local aliases
    if r.random() < 0.4:
        parts.append("local t_concat = table.concat")
    # Some prints / expressions to ensure runtime paths
    for _ in range(r.randint(1, 4)):
        call = r.choice(BUILTINS)
        arg = r.choice([
            _rand_string_literal(r), _rand_number(r), "{}", "{1,2,3}",
            r.choice(["true", "false", "nil"])
        ])
        parts.append(f"{call}({arg})")
    # A random function
    parts.append(_gen_function(r))
    # A gsub-like pattern usage in pure Lua to exercise string library
    if r.random() < 0.5:
        s = _rand_string_literal(r)
        parts.append(f"local _=string.gsub({s}, 'a', 'b')")
    # Optionally return a table as chunk result
    if r.random() < 0.5:
        parts.append("return {status='ok', n=42}")

    src = "\n".join(parts) + "\n"
    # Trim to target_bytes if needed without breaking validity too much (Lua ignores trailing comments)
    if len(src.encode('utf-8')) > target_bytes:
        # Append a comment trailer so truncation less likely to cut syntax-critical part; then slice
        src = (src + "-- end\n")
        enc = src.encode('utf-8')[:target_bytes]
        # Ensure we do not cut in the middle of a multi-byte char: back up to valid UTF-8
        while True:
            try:
                src = enc.decode('utf-8')
                break
            except UnicodeDecodeError as e:
                enc = enc[:e.start]
        # Best-effort: ensure ends with newline
        if not src.endswith("\n"):
            src += "\n"
    return src

def _gen_chunk_name(r: random.Random) -> str:
    base_opts = [
        "=fuzzbuf", "=@virtual", "=@memory", "=test", "@file.lua", "@/tmp/f.lua",
    ]
    if r.random() < 0.6:
        return r.choice(base_opts)
    # Randomized name; include unicode and path-like
    prefix = r.choice(['=', '@'])
    stem = ''.join(r.choice(string.ascii_letters + string.digits + "-_./") for _ in range(r.randint(3, 20)))
    return prefix + stem

def _pack_fields(fields: List[bytes]) -> bytes:
    # Pack multiple C-strings separated by NUL. FUZZ_PARAM_STR typically reads sequentially;
    # even if not, providing a single first string (chunk) is critical; name as second helps when used.
    return b"\x00".join(fields)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Decide approximate total size budget
    total_budget = r.randint(256, 2048)

    # Generate a valid Lua source chunk
    # Leave room for name and some extras (~64-128 bytes)
    name_budget = 128
    chunk = _gen_chunk(r, max(64, total_budget - name_budget))

    # Generate chunk name per C string (NUL-terminated when packed with separator)
    name = _gen_chunk_name(r)

    # Occasionally prepend Lua byte order mark or comment to exercise lexer path
    if r.random() < 0.2:
        chunk = "\ufeff" + chunk

    # Assemble payload: [chunk] NUL [name] NUL [spare]
    # Add a spare auxiliary string that the harness might consume elsewhere
    spare = _rand_string_literal(r)

    payload = _pack_fields([
        chunk.encode('utf-8'),
        name.encode('utf-8'),
        spare.encode('utf-8')
    ])

    # Ensure within hard limit
    return payload[:4096]
